'use client'

import { useActionState } from 'react'

const initialState = {
  success: false,
  error: '' as string,
}

export default function ContactForm() {
  async function submitContactMessage(prevState: typeof initialState, formData: FormData) {
    'use server'

    const name = formData.get('name')?.toString().trim()
    const email = formData.get('email')?.toString().trim()
    const message = formData.get('message')?.toString().trim()

    // JavaScript validation: check that all fields are provided
    if (!name) {
      return { success: false, error: 'Name is required.' }
    }
    if (!email) {
      return { success: false, error: 'Email is required.' }
    }
    if (!message) {
      return { success: false, error: 'Message is required.' }
    }

    // TODO: Save contact message (e.g., to database, send email, etc.)
    return { success: true, error: '' }
  }

  const [state, formAction, pending] = useActionState(submitContactMessage, initialState)

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input type="text" id="name" name="name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input type="email" id="email" name="email" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" rows={5} required />
        </div>
        {state?.error && <p role="alert">{state.error}</p>}
        {state?.success && <p>Thank you for your message! We&apos;ll get back to you soon.</p>}
        <button type="submit" disabled={pending}>
          {pending ? 'Sending...' : 'Send Message'}
        </button>
      </form>
    </div>
  )
}

